INSERT INTO articles (
  slug, title, excerpt, category, cover_image, content_html, status, author,
  seo_title, seo_description, published_at, created_at, updated_at
) VALUES ('uu-dai-lai-thu-vf-3-demo', 'Trải nghiệm VF 3 tại showroom demo', 'Đăng ký lái thử VF 3 để cảm nhận thiết kế nhỏ gọn, khả năng vận hành linh hoạt và không gian phù hợp cho phố thị.', 'Ưu đãi', '/images/news-1.webp', '<p>VF 3 là mẫu ô tô điện mini được nhiều khách hàng quan tâm nhờ thiết kế cá tính và khả năng di chuyển linh hoạt trong đô thị. Chương trình lái thử demo tại showroom giúp khách hàng trải nghiệm thực tế trước khi quyết định.</p><p>Khách hàng có thể đăng ký trực tuyến, chọn khung giờ phù hợp và nhận tư vấn từ đội ngũ kinh doanh. Thông tin trên trang là dữ liệu mẫu cho mục đích demo.</p><p>Để đăng ký, vui lòng sử dụng form Đăng ký lái thử hoặc liên hệ hotline demo trên website.</p>', 'published', 'VinFast Demo', 'Trải nghiệm VF 3 tại showroom demo', 'Đăng ký lái thử VF 3 để cảm nhận thiết kế nhỏ gọn và khả năng vận hành linh hoạt trong đô thị.', '2026-11-10T00:00:00.000Z', '2026-11-26T00:00:00.000Z', '2026-11-26T00:00:00.000Z')
