INSERT INTO articles (
  slug, title, excerpt, category, cover_image, content_html, status, author,
  seo_title, seo_description, published_at, created_at, updated_at
) VALUES ('dich-vu-5-sao-demo', 'Quy trình dịch vụ 5 sao tại xưởng demo', 'Từ tiếp nhận, kiểm tra đến bàn giao xe, quy trình dịch vụ được thiết kế để mang lại trải nghiệm thuận tiện và minh bạch.', 'Dịch vụ', '/images/news-2.webp', '<p>Xưởng dịch vụ demo tiếp nhận xe theo quy trình chuẩn: ghi nhận tình trạng, kiểm tra tổng quát và tư vấn hạng mục cần thực hiện. Khách hàng được thông báo trước khi tiến hành sửa chữa.</p><p>Trang thiết bị và quy trình trong nội dung này là mô phỏng cho website demo. Khi triển khai thật, đại lý sẽ cập nhật thông tin xưởng, thời gian và chính sách thực tế.</p><p>Khách hàng có thể đặt lịch dịch vụ trực tuyến để giảm thời gian chờ tại showroom.</p>', 'published', 'VinFast Demo', 'Quy trình dịch vụ 5 sao tại xưởng demo', 'Quy trình tiếp nhận, kiểm tra và bàn giao xe tại xưởng dịch vụ demo.', '2026-11-06T00:00:00.000Z', '2026-11-26T00:00:00.000Z', '2026-11-26T00:00:00.000Z')
