INSERT INTO articles (
  slug, title, excerpt, category, cover_image, content_html, status, author,
  seo_title, seo_description, published_at, created_at, updated_at
) VALUES ('kinh-nghiem-cham-soc-pin-demo', '5 lưu ý chăm sóc pin xe điện', 'Duy trì thói quen sạc hợp lý, tránh để pin cạn kiệt và kiểm tra định kỳ giúp kéo dài tuổi thọ pin.', 'Kinh nghiệm', '/images/news-3.webp', '<p>Pin là bộ phận quan trọng của xe điện. Để duy trì hiệu suất, nên hạn chế để pin ở mức quá thấp trong thời gian dài và tránh sạc quá đầy nếu không cần thiết.</p><p>Nên sạc xe ở nơi khô ráo, thoáng mát, sử dụng thiết bị sạc phù hợp với hướng dẫn của nhà sản xuất. Kiểm tra định kỳ giúp phát hiện sớm các dấu hiệu bất thường.</p><p>Nội dung trên là thông tin tham khảo cho website demo, không thay thế hướng dẫn chính thức từ VinFast.</p>', 'published', 'VinFast Demo', '5 lưu ý chăm sóc pin xe điện', 'Các lưu ý cơ bản để duy trì hiệu suất và kéo dài tuổi thọ pin xe điện.', '2026-11-01T00:00:00.000Z', '2026-11-26T00:00:00.000Z', '2026-11-26T00:00:00.000Z')
